<template><main class="login-page"><el-card class="login-card"><p class="eyebrow">TOSHIO RESTAURANT</p><h1>管理员登录</h1><p>登录后管理店铺、菜单和订单。</p><el-form @submit.prevent="login"><el-form-item label="管理员密码"><el-input v-model="password" type="password" show-password autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" :loading="loading" class="login-submit" @click="login">登录后台</el-button></el-form></el-card></main></template>
<script setup lang="ts">import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from '../api';const route=useRoute(),router=useRouter(),password=ref(''),error=ref(''),loading=ref(false);async function login(){error.value='';if(!password.value){error.value='请输入管理员密码';return}loading.value=true;try{await api.post('/auth/login',{password:password.value});const target=typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/admin')?route.query.redirect:'/admin';await router.replace(target)}catch(e:any){error.value=e.message}finally{loading.value=false}}</script>
